const paths={global:'data/metricas_globales.csv',localidades:'data/metricas_por_localidad.csv',franjas:'data/metricas_por_franja.csv',importancia:'data/importancia.csv'};
const parseCSV=text=>{const rows=text.replace(/^\uFEFF/,'').trim().split(/\r?\n/).map(r=>r.split(','));const head=rows.shift();return rows.map(r=>Object.fromEntries(head.map((h,i)=>[h,r[i]])))};
const num=(v,d=0)=>Number(v||d);const pct=v=>`${(num(v)*100).toLocaleString('es-CO',{minimumFractionDigits:1,maximumFractionDigits:1})}%`;const int=v=>num(v).toLocaleString('es-CO');
const state={};
async function load(){for(const [key,path] of Object.entries(paths)){state[key]=parseCSV(await fetch(path).then(r=>{if(!r.ok)throw new Error(path);return r.text()}))}state.global=state.global.find(r=>r.Modelo==='Random Forest');setup();render()}
function setup(){const loc=document.querySelector('#localidad'),fra=document.querySelector('#franja');state.localidades.forEach(r=>loc.add(new Option(title(r.Localidad),r.Localidad)));state.franjas.forEach(r=>fra.add(new Option(r.Franja_Horaria,r.Franja_Horaria)));loc.addEventListener('change',render);fra.addEventListener('change',render)}
function title(s){return s.toLocaleLowerCase('es').replace(/(^|\s)\S/g,m=>m.toUpperCase())}
function activeRow(){const l=document.querySelector('#localidad').value,f=document.querySelector('#franja').value;if(l!=='GLOBAL')return state.localidades.find(r=>r.Localidad===l);if(f!=='GLOBAL')return state.franjas.find(r=>r.Franja_Horaria===f);return state.global}
function render(){const row=activeRow(),l=document.querySelector('#localidad').value,f=document.querySelector('#franja').value;['F1','AUC_ROC','Precision','Recall'].forEach(k=>document.querySelector(`#kpi-${k==='AUC_ROC'?'auc':k.toLowerCase()}`).textContent=pct(row[k]));['TN','FP','FN','TP'].forEach(k=>document.querySelector(`#${k.toLowerCase()}`).textContent=int(row[k]));document.querySelector('#scope-note').textContent=l!=='GLOBAL'?`Resultados de ${title(l)} en todas las franjas.`:f!=='GLOBAL'?`Resultados de la franja ${f.toLowerCase()} en todas las localidades.`:'Vista global del conjunto de evaluación.';drawLocalities(l);drawFranjas(f);drawImportance();document.querySelector('#candelaria-note').classList.toggle('hidden',l!=='CANDELARIA')}
function drawLocalities(selected){const top=[...state.localidades].sort((a,b)=>num(b.F1)-num(a.F1));document.querySelector('#locality-chart').innerHTML=top.map(r=>`<div class="bar-row ${r.Localidad===selected?'selected':''}"><span class="name">${title(r.Localidad)}</span><span class="track"><i class="fill" style="--w:${num(r.F1)*200}%"></i></span><strong>${pct(r.F1)}</strong></div>`).join('')}
function drawFranjas(selected){document.querySelector('#franja-chart').innerHTML=state.franjas.map(r=>`<div class="column ${r.Franja_Horaria===selected?'selected':''}"><b>${pct(r.Recall)}</b><i style="--h:${num(r.Recall)*100}%"></i><span>${r.Franja_Horaria}</span></div>`).join('')}
function drawImportance(){const max=Math.max(...state.importancia.map(r=>num(r.Caida_AP_Media)));document.querySelector('#importance-chart').innerHTML=state.importancia.slice(0,7).map(r=>`<div class="bar-row"><span class="name">${r.Variable.replaceAll('_',' ')}</span><span class="track"><i class="fill" style="--w:${num(r.Caida_AP_Media)/max*100}%"></i></span><strong>${num(r.Caida_AP_Media).toFixed(3)}</strong></div>`).join('')}
load().catch(()=>{document.querySelector('main').insertAdjacentHTML('afterbegin','<div class="callout"><strong>No fue posible cargar los datos.</strong> Abre el dashboard desde un servidor local o desde su versión publicada.</div>')});
